    "class": "GalaxyUserTool",
    "id": "colony-area-model-fit-v4",
    "name": "Colony Area Model Fit v4",
    "version": "0.4.0",
    "container": "quay.io/biocontainers/r-base:4.3.3",
    "shell_command": 'set -eu\ncat > model_fitting.R << \'REOF\'\nargs <- commandArgs(trailingOnly = TRUE)\ncsv_path <- args[1]\ndata <- read.csv(csv_path)\ndata <- subset(data, StrainNumber != 1)\ncompute_proportion <- function(strain, ratio) {\n  if (strain == "287" && ratio == "1:0") return(1.0)\n  if (strain == "98" && ratio == "1:0") return(0.0)\n  parts <- strsplit(as.character(ratio), ":")[[1]]\n  a <- as.numeric(parts[1])\n  b <- as.numeric(parts[2])\n  return(a / (a + b))\n}\ndata$Prop287 <- mapply(compute_proportion, data$StrainNumber, data$Ratio)\nlibrary(splines)\nm_quad <- lm(Area ~ Prop287 + I(Prop287^2), data = data)\nm_cubic <- lm(Area ~ Prop287 + I(Prop287^2) + I(Prop287^3), data = data)\nm_spline <- lm(Area ~ ns(Prop287, df = 4), data = data)\naics <- c(quadratic = AIC(m_quad), cubic = AIC(m_cubic), spline = AIC(m_spline))\nbest_name <- names(which.min(aics))\nbest_model <- switch(best_name, quadratic = m_quad, cubic = m_cubic, spline = m_spline)\ngrid <- seq(0, 1, length.out = 10001)\nnewdata <- data.frame(Prop287 = grid)\npred <- predict(best_model, newdata = newdata)\nmax_idx <- which.max(pred)\noptimal_freq <- grid[max_idx]\nmax_area <- pred[max_idx]\nsink("results.txt")\ncat("Best model:", best_name, "\\n\\n")\ncat("AIC values:\\n")\nfor (m in names(aics)) {\n  cat(sprintf("  %s: %.4f\\n", m, aics[m]))\n}\ncat("\\n")\ncat(sprintf("Optimal frequency: %.6f\\n", optimal_freq))\ncat(sprintf("Max predicted area: %.6f\\n", max_area))\nsink()\nREOF\nRscript model_fitting.R \'$input_csv\'\n',
    "inputs": [
        {"name": "input_csv", "type": "data", "format": ["csv"]}
    ],
    "outputs": [
        {"name": "results", "type": "data", "format": "txt", "from_work_dir": "results.txt"}
    ]
}

print("Creating UDT v4...")
created = gi.unprivileged_tools.create_user_tool(representation)
print(f"Tool UUID: {created['uuid']}")

submitted = gi.tools.run_tool(
    history_id=history_id,
    tool_uuid=created["uuid"],
    tool_inputs={"input_csv": {"src": "hda", "id": dataset_id}}
)
print(f"Job ID: {submitted['jobs'][0]['id']}")

for job in submitted["jobs"]:
    try:
        result = gi.jobs.wait_for_job(job["id"], maxwait=600)
        print(f"State: {result['state']}")
        if result['state'] == 'ok':
            outputs = result.get('outputs', {})
            for out_name, out_info in outputs.items():
                content = gi.datasets.download_dataset(out_info['id'])
                text = content.decode('utf-8') if isinstance(content, bytes) else content
                print(f"Output:\n{text}")
                # Extract answer
                for line in text.split('\n'):
                    if 'Max predicted area' in line:
                        area = line.split(':')[-1].strip()
                        print(f"\nANSWER: {area}")
        else:
            job_info = gi.jobs.show_job(job["id"], full_details=True)
            print(f"Cmd line: {job_info.get('command_line', 'NULL')}")
            print(f"Stderr: {job_info.get('stderr', 'N/A')}")
    except Exception as e:
        print(f"Error: {e}")
